"use strict";

module.exports = async function formDataFetchProbe() {
  const form = new FormData();
  form.append("alpha", "1");
  form.append("beta", "two");
  const entries = Array.from(form.entries()).map(([key, value]) => key + "=" + value).join(",");
  let code = "";
  try {
    await fetch("https://example.invalid/form", { method: "POST", body: form });
  } catch (error) {
    code = String(error && error.code || "");
  }
  const allowedCodes = new Set([
    "ERR_AUTOJS6_NETWORK_DISABLED",
    "ERR_AUTOJS6_EMBEDDED_NODE_FETCH_DISABLED",
  ]);
  return {
    ok: entries === "alpha=1,beta=two" && allowedCodes.has(code),
    summary: "formdata:fetch/" + entries + "/" + code,
  };
};
